## From Text to Trusted Value

Validating age requires three steps: parse the text, check it's reasonable, and return the clean number.

### Step 1: Parse

```xiom
fn parse_age(input: Str) -> Result[Int, Str] {
  return string.str_to_int(input);
}
```

### Step 2: Validate Range

```xiom
fn validate_age(age: Int) -> Result[Int, Str] {
  if age < 0 {
    return Err("Age cannot be negative (you entered " + string.int_to_str(age) + ")");
  }
  if age == 0 {
    return Err("Age cannot be zero");
  }
  if age > 150 {
    return Err("Age cannot exceed 150 (you entered " + string.int_to_str(age) + ")");
  }
  return Ok(age);
}
```

### Step 3: Categorize

```xiom
fn categorize_age(age: Int) -> Str {
  if age < 13 { return "Child"; }
  if age < 20 { return "Teenager"; }
  if age < 65 { return "Adult"; }
  return "Senior";
}
```

### The Full Validator

```xiom
fn process_age(input: Str) -> Result[Str, Str] {
  let age = parse_age(input)?;
  let valid_age = validate_age(age)?;
  let category = categorize_age(valid_age);
  return Ok(string.int_to_str(valid_age) + " years old — " + category);
}

fn main() -> Int {
  match process_age("25") {
    Ok(msg) => io.println(msg),   // 25 years old — Adult
    Err(e) => io.println(e),
  };
  match process_age("10") {
    Ok(msg) => io.println(msg),   // 10 years old — Child
    Err(e) => io.println(e),
  };
  match process_age("-5") {
    Ok(msg) => io.println(msg),
    Err(e) => io.println(e),      // Age cannot be negative
  };
  match process_age("200") {
    Ok(msg) => io.println(msg),
    Err(e) => io.println(e),      // Age cannot exceed 150
  };
  match process_age("old") {
    Ok(msg) => io.println(msg),
    Err(e) => io.println(e),      // Parse error
  };
  return 0;
}
```

### Comprehensive Testing

```xiom
fn test_cases() {
  io.println(process_age("0").unwrap_or("Invalid"));    // Age cannot be zero
  io.println(process_age("42").unwrap_or("Invalid"));   // 42 years old — Adult
  io.println(process_age("151").unwrap_or("Invalid"));  // Age cannot exceed 150
  io.println(process_age("").unwrap_or("Invalid"));     // Parse error
}
```

