use xiom.io;

use xiom.string;
fn parse_age(input: Str) -> Result[Int, Str] {
  return string.str_to_int(input);
}

fn validate_age(age: Int) -> Result[Int, Str] {
  if age < 0 { return Err("Age cannot be negative"); }
  if age == 0 { return Err("Age cannot be zero"); }
  if age > 150 { return Err("Age cannot exceed 150"); }
  return Ok(age);
}

fn categorize_age(age: Int) -> Str {
  if age < 13 { return "Child"; }
  if age < 20 { return "Teen"; }
  if age < 65 { return "Adult"; }
  return "Senior";
}

fn process_age(input: Str) -> Result[Str, Str] {
  let age = parse_age(input)?;
  let valid = validate_age(age)?;
  let cat = categorize_age(valid);
  return Ok(to_string(valid) + " — " + cat);
}

fn main() -> Int {
  io.println(process_age("16").unwrap_or("Invalid").to_str());
  io.println(process_age("42").unwrap_or("Invalid").to_str());
  io.println(process_age("-1").unwrap_or("Invalid").to_str());
  io.println(process_age("200").unwrap_or("Invalid").to_str());
  io.println(process_age("hello").unwrap_or("Invalid").to_str());
  return 0;
}
